/* Twitter Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Twitter Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 300 50% 100%;
    --foreground: 210.09 19.2% 7.94%;
    --card: 300 0% 97.37%;
    --card-foreground: 210.09 19.2% 7.94%;
    --popover: 300 50% 100%;
    --popover-foreground: 210.09 19.2% 7.94%;
    --primary: 203.9 87.4% 52.92%;
    --primary-foreground: 300 50% 100%;
    --secondary: 210.09 19.2% 7.94%;
    --secondary-foreground: 300 50% 100%;
    --muted: 0 0% 89.56%;
    --muted-foreground: 210.09 19.2% 7.94%;
    --accent: 211.57 63.86% 92.98%;
    --accent-foreground: 203.9 87.4% 52.92%;
    --destructive: 355.88 91.79% 54.04%;
    --destructive-foreground: 300 50% 100%;
    --border: 201.44 25.19% 90.78%;
    --input: 300 0% 97.37%;
    --ring: 202.46 89.54% 52.14%;
    --chart-1: 203.9 87.4% 52.92%;
    --chart-2: 159.77 99.83% 36.06%;
    --chart-3: 42.06 92.44% 56.04%;
    --chart-4: 145.92 71.53% 43.87%;
    --chart-5: 341.12 75.33% 50.41%;
    --radius: 1.3rem;
    --sidebar: 300 0% 97.37%;
    --sidebar-foreground: 210.09 19.2% 7.94%;
    --sidebar-primary: 203.9 87.4% 52.92%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 211.57 63.86% 92.98%;
    --sidebar-accent-foreground: 203.9 87.4% 52.92%;
    --sidebar-border: 205 25.68% 90.96%;
    --sidebar-ring: 202.46 89.54% 52.14%;
    --font-sans: Open Sans, sans-serif;
    --font-serif: Georgia, serif;
    --font-mono: Menlo, monospace;
    --shadow-color: 202.82 89.12% 53.14%;
    --shadow-opacity: 0;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 2px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-sm:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-md:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 2px 4px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-lg:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 4px 6px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xl:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 8px 10px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-2xl: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 0 0% 0%;
    --foreground: 324 0% 90.85%;
    --card: 228.12 11.99% 10.15%;
    --card-foreground: 340 0% 85.7%;
    --popover: 0 0% 0%;
    --popover-foreground: 324 0% 90.85%;
    --primary: 203.91 87.41% 52.93%;
    --primary-foreground: 300 50% 100%;
    --secondary: 300 0% 94.75%;
    --secondary-foreground: 210.09 19.2% 7.94%;
    --muted: 300 0% 9.5%;
    --muted-foreground: 209.98 4.35% 45.91%;
    --accent: 205.82 64.44% 7.66%;
    --accent-foreground: 203.91 87.41% 52.93%;
    --destructive: 355.88 91.79% 54.04%;
    --destructive-foreground: 300 50% 100%;
    --border: 300 0% 15.03%;
    --input: 207.65 29.1% 18.23%;
    --ring: 202.46 89.54% 52.14%;
    --chart-1: 203.9 87.4% 52.92%;
    --chart-2: 159.77 99.83% 36.06%;
    --chart-3: 42.06 92.44% 56.04%;
    --chart-4: 145.92 71.53% 43.87%;
    --chart-5: 341.12 75.33% 50.41%;
    --radius: 1.3rem;
    --sidebar: 228.12 11.99% 10.15%;
    --sidebar-foreground: 340 0% 85.7%;
    --sidebar-primary: 202.46 89.54% 52.14%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 205.82 64.44% 7.66%;
    --sidebar-accent-foreground: 203.91 87.41% 52.93%;
    --sidebar-border: 205.76 14.33% 26.13%;
    --sidebar-ring: 202.46 89.54% 52.14%;
    --font-sans: Open Sans, sans-serif;
    --font-serif: Georgia, serif;
    --font-mono: Menlo, monospace;
    --shadow-color: 202.82 89.12% 53.14%;
    --shadow-opacity: 0;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 2px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-sm:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-md:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 2px 4px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-lg:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 4px 6px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xl:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 8px 10px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-2xl: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  }

}
